head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusMode]<br/>GridView 컴포넌트의 Body 또는 Footer 영역 선택 시 포커스 되는 형식을 설정합니다.",
    "validation" : [
        "focusDefaultColumn=true 이면 RowNumber/RowStatus Column 도 포커스 대상에 포함됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - focusMode 는 포커스 대상(셀/Row) 개념이 필요한 cell/both 중 con 으로 선택
//  - focusDefaultColumn (true/false) 을 con 으로 노출하여 RowNum/RowStatus Column 포커스 포함 여부 검증
//  - rowNumVisible / rowStatusVisible 는 RowNum / RowStatus Column 가시화를 위해 true 하드코딩
//  - selectedCellColor(red) / selectedRowColor(blue) 를 서로 다른 색으로 하드코딩하여 포커스 결과를 색으로 구분
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    let properties = {
        dataList          : "data:dlt_bind",
        focusMode         : con_focusMode.getValue(),
        focusDefaultColumn: con_focusDefaultColumn.getText(),
        rowNumVisible     : "true",
        rowStatusVisible  : "true",
        selectedCellColor : "red",
        selectedRowColor  : "blue"
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    //  - oncellclick      : 일반 Body Cell 클릭 시 포커스 처리/배경색 출력
    //  - onrownumclick    : focusDefaultColumn=true 일 때 RowNum Column 클릭 시 발생
    //  - onrowstatusclick : focusDefaultColumn=true 일 때 RowStatus Column 클릭 시 발생
    let eList = $c.gcm.createEList(["oncellclick", "onrownumclick", "onrowstatusclick"]);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="focusMode=' + properties.focusMode + ' / focusDefaultColumn=' + properties.focusDefaultColumn + ' / rowNumVisible=true / rowStatusVisible=true (고정) / selectedCellColor=red / selectedRowColor=blue 로 GridView 생성. RowNum/RowStatus Cell 또는 Body Cell 을 클릭하면 포커스 대상 포함 여부 출력"', '', 'label1');

    // dataList 생성 (헬퍼와 동일하게 col1~col4 컬럼 구성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// RowNum / RowStatus / 일반 Body Cell 의 포커스 적용 상태(focusedTd 클래스 + 배경색)를 출력하는 공통 함수
//  - focusDefaultColumn=true  : RowNum/RowStatus Cell 도 포커스 대상 → 클릭/포커스 시 focusedTd 부여, 배경색 적용
//  - focusDefaultColumn=false : RowNum/RowStatus 는 포커스 대상에서 제외 → focusedTd 미부여
scwin.printFocusState = function (rowIndex) {
    let bottom = wf_body_bottom.getObj("scwin");

    let numTd    = document.querySelector("td[id*='target1_headerRowNumber_bodyRow_" + rowIndex + "']");
    let statusTd = document.querySelector("td[id*='target1_headerRowStatus_bodyRow_" + rowIndex + "']");

    let numFocused    = numTd ? numTd.className.indexOf("focusedTd") >= 0 : false;
    let statusFocused = statusTd ? statusTd.className.indexOf("focusedTd") >= 0 : false;
    let numColor      = numTd ? window.getComputedStyle(numTd).backgroundColor : "(cell 없음)";
    let statusColor   = statusTd ? window.getComputedStyle(statusTd).backgroundColor : "(cell 없음)";

    bottom.setReturnValue("[focusDefaultColumn] " + target1.options.focusDefaultColumn + " / focusMode=" + target1.options.focusMode);
    bottom.setReturnValue("[RowNum Cell 포커스 대상 포함] focusedTd=" + numFocused + " / 배경색 " + numColor);
    bottom.setReturnValue("[RowStatus Cell 포커스 대상 포함] focusedTd=" + statusFocused + " / 배경색 " + statusColor);
}



// oncellclick : 일반 Body Cell 을 클릭하면 발생 (RowNum/RowStatus 가 아닌 데이터 셀)
//  - focusDefaultColumn 과 무관하게 일반 Cell 은 포커스됨. 비교 기준으로 클릭한 Row 의 RowNum/RowStatus 포커스 포함 여부 출력
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    // 포커스 배경색/클래스 적용은 클릭 처리 직후 반영되므로 다음 tick 에서 read
    setTimeout(function () {
        bottom.setReturnValue("=====target1_oncellclick (Body Cell " + rowIndex + "," + columnIndex + " 클릭)=====");
        scwin.printFocusState(rowIndex);
    }, 0);
}



// onrownumclick : focusDefaultColumn=true 일 때 RowNum Column Body Cell 클릭 시 발생 (false 면 미발생)
scwin.target1_onrownumclick = function (rowIndex) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    setTimeout(function () {
        bottom.setReturnValue("=====target1_onrownumclick (RowNum Cell Row " + rowIndex + " 클릭) → focusDefaultColumn=true 이므로 RowNum 이 포커스 대상에 포함되어 이벤트 발생=====");
        scwin.printFocusState(rowIndex);
    }, 0);
}



// onrowstatusclick : focusDefaultColumn=true 일 때 RowStatus Column Body Cell 클릭 시 발생 (false 면 미발생)
scwin.target1_onrowstatusclick = function (rowIndex) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    setTimeout(function () {
        bottom.setReturnValue("=====target1_onrowstatusclick (RowStatus Cell Row " + rowIndex + " 클릭) → focusDefaultColumn=true 이므로 RowStatus 가 포커스 대상에 포함되어 이벤트 발생=====");
        scwin.printFocusState(rowIndex);
    }, 0);
}
